<script setup lang="ts">
import { computed, ref, watch } from 'vue';import CredentialRestore from './CredentialRestore.vue';const credentialLocked=ref(false);import ActionIcon from './ActionIcon.vue';import PageActions from './PageActions.vue';import DataGrid from './DataGrid.vue';import SnapshotGate from './SnapshotGate.vue';import SnapshotComparison from './SnapshotComparison.vue';import { snapshotItems,selectSnapshotItems,itemsToCurrent } from '../config/snapshot-items.mjs';import { captureScheduleSource } from '../data/snapshot-schedule';import { readSnapshot } from '../data/stored-snapshots';import { openSnapshotMerge } from '../data/merge-session';import { queueChange } from '../data/pending-rollouts';import { containsSecretValues } from '../config/backup-zip.mjs';
const props=defineProps<{snapshot?:any;selectedIds:string[]}>();const emit=defineEmits<{close:[];'update:selectedIds':[ids:string[]]}>();const picked=ref<string[]>([]),ready=ref(false),confirmed=ref(false),error=ref(''),message=ref(''),baseline=ref<any>(null);const gate=ref<any>(null);watch(()=>props.snapshot,s=>{picked.value=[];confirmed.value=false;ready.value=false;error.value='';message.value='';baseline.value=s?captureScheduleSource():null;},{immediate:true});
const items=computed(()=>props.snapshot?snapshotItems(props.snapshot.current):[]);const all=computed({get:()=>items.value.length>0&&items.value.every((i:any)=>picked.value.includes(i.id)),set:(value:boolean)=>picked.value=value?items.value.map((i:any)=>i.id):[]});const selection=computed(()=>props.snapshot?selectSnapshotItems(props.snapshot.current,picked.value):{items:[],added:[],current:{}});const present=computed(()=>itemsToCurrent(snapshotItems(baseline.value||{}).filter((i:any)=>selection.value.items.some((s:any)=>s.id===i.id))));
const credentialRestoreBlocked=computed(()=>selection.value.items.some((item:any)=>item.type==='resource'&&item.value.kind==='Secret')||containsSecretValues(selection.value.current));
const sourceCatalogItems=computed(()=>selection.value.items.filter((item:any)=>item.type==='configuration'&&item.value.kind==='DnsSourceCatalog'));
const sourceCatalogMixed=computed(()=>sourceCatalogItems.value.length>0&&(sourceCatalogItems.value.length!==1||selection.value.items.length!==1));
watch(picked,()=>{confirmed.value=false;});
function restore(){if(credentialRestoreBlocked.value||credentialLocked.value){error.value='Select credentials separately for DNS Credential Restore. No configuration drafts were prepared.';return;}if(sourceCatalogMixed.value){error.value='Restore one DNS source catalog separately from zones, records, credentials, and other configuration. No drafts were prepared.';return;}if(!picked.value.length||selection.value.missing?.length||!confirmed.value||!gate.value?.checkNow())return;try{if(JSON.stringify(captureScheduleSource())!==JSON.stringify(baseline.value))throw new Error('Configuration changed during review. Reopen the snapshot and review again.');for(const item of selection.value.items){if(item.type==='service')continue;if(item.type==='proposal'){queueChange({...item.value,id:`restore:${item.id}`,category:`Restore Draft: ${item.value.category}`});continue;}const resource=item.type==='resource'?[item.value]:item.value.resources||[];queueChange({id:`restore:${item.id}`,category:`Restore ${item.type==='resource'?item.value.kind:item.type}`,name:item.name,namespace:item.namespace||'',resources:resource,restoreSnapshotId:props.snapshot.id,snapshotScope:props.snapshot.current?.snapshotScope,configuration:item.type==='resource' ? (item.value.kind==='Secret' ? {restoreSecretConfirmed:true} : undefined) : item.value});}message.value=`${selection.value.items.length} selected items and dependencies prepared in Pending Rollouts. Nothing has been applied.`;confirmed.value=false;}catch(e){error.value=e instanceof Error?e.message:'Restore preparation failed.';}}
function openMerge(){openSnapshotMerge(props.selectedIds);}
</script>
<template><PageActions><button v-if="selectedIds.length>=2" type="button" class="header-action" @click="openMerge"><ActionIcon icon="merge"/>Merge Snapshots</button></PageActions><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><section v-if="snapshot" class="snapshot-operation"><h3>Select Items To Restore</h3><DataGrid><thead><tr><th class="selection-cell"><input v-model="all" type="checkbox" aria-label="Select All Restoration Items" :disabled="credentialLocked"></th><th>Item</th><th>Type</th><th>Namespace</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td class="selection-cell"><input v-model="picked" :value="item.id" type="checkbox" :disabled="credentialLocked" :aria-label="`Restore ${item.name} ${item.type==='resource'?item.value.kind:item.type} ${item.namespace || 'Global'}`"></td><td>{{ item.name }}</td><td>{{ item.type==='resource'?item.value.kind:item.type }}</td><td>{{ item.namespace || 'Global' }}</td></tr></tbody></DataGrid><CredentialRestore :key="snapshot.id" :snapshot="snapshot" :items="selection.items" :missing="selection.missing" @locked="credentialLocked=$event"/><p v-if="selection.added.length">Required Dependencies Included: {{ selection.added.map((i:any)=>i.name).join(', ') }}</p><p v-if="selection.missing?.length" role="alert">Missing Required Dependencies: {{ selection.missing.join(', ') }}. Restore is blocked; choose a snapshot containing these resources.</p><p v-if="sourceCatalogMixed" role="alert">Restore one DNS source catalog separately from all other configuration.</p><template v-if="picked.length&&!credentialRestoreBlocked&&!credentialLocked"><SnapshotComparison :current="present" :saved="selection.current"/><SnapshotGate ref="gate" :data="baseline" :scope-key="JSON.stringify(baseline)" @ready="ready=$event;confirmed=false"/><label><input v-model="confirmed" type="checkbox" :disabled="!ready||credentialRestoreBlocked||sourceCatalogMixed">Confirm Selected Restoration Drafts</label><button type="button" :disabled="!ready||!confirmed||!!selection.missing?.length||credentialRestoreBlocked||sourceCatalogMixed" @click="restore">Prepare Selected Restore</button></template><button type="button" class="secondary" @click="emit('close')">Cancel</button></section></template>
<style scoped>.snapshot-operation{margin-top:20px;padding:20px;background:var(--input-bg,#1c2430);border:1px solid #619bd9;border-radius:6px}h3{margin:0 0 16px;font-size:15px}table{width:100%;border-collapse:collapse;font-size:12px}td,th{padding:10px 8px;border-bottom:1px solid #384352;text-align:left}label{display:flex;align-items:center;gap:10px;margin:16px 0;font-size:12px}select{padding:10px;background:#242c38;border:1px solid #384352;border-radius:5px;color:inherit;max-width:100%}button{padding:10px 14px;background:#326fb4;color:white;border:0;border-radius:5px;cursor:pointer;margin-right:10px;font:inherit;font-size:12px}button:disabled{opacity:.5;cursor:not-allowed}.secondary{background:transparent;border:1px solid #619bd9}p{font-size:12px;line-height:1.7}summary{cursor:pointer;color:#a9d2ff}</style>
